package com.alpharip.staffmod.BuildTimelapse.core;
import com.alpharip.staffmod.BuildTimelapse.timeline.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Local-only project metadata, timeline markers and clip-track persistence. */
public final class FileProjectStore implements ProjectStore {
 private static final int MAX_ITEMS=100000;private final File root;
 public FileProjectStore(File r){if(r==null)throw new IllegalArgumentException("root");root=r;}
 public void save(BuildTimelapseProject p,Timeline t)throws IOException{
  if(p==null||t==null)throw new IllegalArgumentException("project/timeline");validateId(p.getId());if((!root.exists()&&!root.mkdirs())||!root.isDirectory())throw new IOException("Cannot create project directory");
  Properties v=new Properties();v.setProperty("format","2");v.setProperty("id",p.getId());v.setProperty("name",p.getName());v.setProperty("world",p.getWorld());v.setProperty("created",Long.toString(p.getCreated()));v.setProperty("notes",p.getNotes());
  List<TimelineMarker> markers=t.getMarkers();v.setProperty("marker.count",Integer.toString(markers.size()));int n=0;for(TimelineMarker m:markers){String k="marker."+(n++)+".";v.setProperty(k+"time",Long.toString(m.getTimeMillis()));v.setProperty(k+"label",m.getLabel());v.setProperty(k+"kind",m.getKind().name());}
  List<TimelineTrack> tracks=t.getTracks();v.setProperty("track.count",Integer.toString(tracks.size()));int ti=0;for(TimelineTrack track:tracks){String tk="track."+ti+".";v.setProperty(tk+"id",track.getId());v.setProperty(tk+"name",track.getName());List<TimelineClip> clips=track.getClips();v.setProperty(tk+"clip.count",Integer.toString(clips.size()));int ci=0;for(TimelineClip clip:clips){String ck=tk+"clip."+ci+++".";v.setProperty(ck+"id",clip.getId());v.setProperty(ck+"source",clip.getSource());v.setProperty(ck+"start",Long.toString(clip.getStart()));v.setProperty(ck+"duration",Long.toString(clip.getDuration()));v.setProperty(ck+"speed",Double.toString(clip.getSpeed()));}ti++;}
  File tmp=new File(root,p.getId()+".tmp"),dst=new File(root,p.getId()+".btproj");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(tmp))){v.store(o,"Build Timelapse project");}
  try{Files.move(tmp.toPath(),dst.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException unsupported){Files.move(tmp.toPath(),dst.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{if(tmp.exists()&&!tmp.delete())tmp.deleteOnExit();}
 }
 private Properties read(String id)throws IOException{validateId(id);File f=new File(root,id+".btproj");if(!f.isFile())throw new FileNotFoundException(f.toString());Properties v=new Properties();try(InputStream in=new BufferedInputStream(new FileInputStream(f))){v.load(in);}String format=v.getProperty("format");if(!"1".equals(format)&&!"2".equals(format))throw new IOException("Unsupported project format");return v;}
 public BuildTimelapseProject load(String id)throws IOException{try{Properties v=read(id);BuildTimelapseProject p=new BuildTimelapseProject(required(v,"id"),required(v,"name"),v.getProperty("world",""),Long.parseLong(required(v,"created")));p.setNotes(v.getProperty("notes",""));return p;}catch(IllegalArgumentException e){throw new IOException("Invalid project metadata for "+id,e);}}
 public Timeline loadTimeline(String id)throws IOException{try{Properties v=read(id);Timeline t=new Timeline();int markers=count(v,"marker.count");for(int n=0;n<markers;n++){String k="marker."+n+".";t.addMarker(new TimelineMarker(Long.parseLong(required(v,k+"time")),required(v,k+"label"),TimelineMarkerKind.valueOf(required(v,k+"kind"))));}
  int tracks=count(v,"track.count");for(int i=0;i<tracks;i++){String k="track."+i+".";TimelineTrack track=new TimelineTrack(required(v,k+"id"),required(v,k+"name"));int clips=count(v,k+"clip.count");for(int j=0;j<clips;j++){String c=k+"clip."+j+".";TimelineClip clip=new TimelineClip(required(v,c+"id"),required(v,c+"source"),Long.parseLong(required(v,c+"start")),Long.parseLong(required(v,c+"duration")));clip.setSpeed(Double.parseDouble(v.getProperty(c+"speed","1")));track.add(clip);}t.addTrack(track);}return t;
 }catch(IllegalArgumentException e){throw new IOException("Invalid timeline data for project "+id,e);}}
 private static int count(Properties p,String key)throws IOException{try{int n=Integer.parseInt(p.getProperty(key,"0"));if(n<0||n>MAX_ITEMS)throw new IOException("Invalid item count: "+key);return n;}catch(NumberFormatException e){throw new IOException("Invalid item count: "+key,e);}}
 private static String required(Properties p,String key)throws IOException{String v=p.getProperty(key);if(v==null)throw new IOException("Missing project property: "+key);return v;}
 private static void validateId(String id)throws IOException{if(id==null||!id.matches("[A-Za-z0-9_-]{1,80}"))throw new IOException("Invalid project id");}
}